#!/usr/bin/env python3
"""Offline IPv6 evidence planner and replay reconciler.

Implements the contract in /app/instruction.md using only the Python 3.11
standard library.  No sockets, no network, no external state.
"""
import argparse
import hashlib
import ipaddress
import json
import os
import re
import sys

MANIFEST_LIMIT = 1 * 1024 * 1024
REPLAY_LIMIT = 96 * 1024 * 1024
MAX_LINES = 300000
MAX_LINE_BYTES = 4096

ID_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,31}$")
V6_SPACE = ipaddress.IPv6Network("2001:db8::/32")

TOP_KEYS = {"version", "seed", "low_count", "attempts", "spacing_ms",
            "timeout_ms", "windows"}
WINDOW_KEYS = {"id", "start_ms", "scopes"}
SCOPE_KEYS = {"id", "prefix", "subnets"}
ROW_KEYS = {"probe_id", "received_ms", "target", "source", "type", "code"}


class InvalidInput(ValueError):
    pass


# --------------------------------------------------------------------------
# JSON helpers with strict rejection rules
# --------------------------------------------------------------------------
def reject_constant(value):
    raise InvalidInput("nonfinite JSON number")


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise InvalidInput("duplicate JSON key")
        result[key] = value
    return result


def decode_json(raw):
    """Decode strict UTF-8 JSON bytes; raise InvalidInput on any failure."""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise InvalidInput("invalid utf-8") from exc
    if text.startswith("\ufeff"):
        raise InvalidInput("BOM not allowed")
    try:
        return json.loads(text, object_pairs_hook=unique_object,
                          parse_constant=reject_constant)
    except InvalidInput:
        raise
    except (ValueError, json.JSONDecodeError) as exc:
        raise InvalidInput("invalid json") from exc


def is_int(value):
    return type(value) is int


# --------------------------------------------------------------------------
# Reading with whole-file limits
# --------------------------------------------------------------------------
def read_bounded(path, limit):
    try:
        st = os.stat(path)
    except OSError as exc:
        raise InvalidInput("cannot stat input: %s" % exc) from exc
    if not os.path.isfile(path):
        raise InvalidInput("input is not a regular file")
    try:
        with open(path, "rb") as handle:
            data = handle.read(limit + 1)
    except OSError as exc:
        raise InvalidInput("cannot read input: %s" % exc) from exc
    if len(data) > limit:
        raise InvalidInput("input exceeds size limit")
    return data


# --------------------------------------------------------------------------
# Manifest validation
# --------------------------------------------------------------------------
def parse_prefix(text):
    if not isinstance(text, str):
        raise InvalidInput("prefix must be a string")
    if "%" in text or any(ch.isspace() for ch in text):
        raise InvalidInput("prefix has zone id or whitespace")
    if "/" not in text:
        raise InvalidInput("prefix must include explicit slash")
    try:
        net = ipaddress.IPv6Network(text, strict=True)
    except (ValueError, ipaddress.AddressValueError,
            ipaddress.NetmaskValueError) as exc:
        raise InvalidInput("invalid prefix: %s" % exc) from exc
    if net.prefixlen not in (56, 64):
        raise InvalidInput("prefix length must be /56 or /64")
    try:
        if not net.subnet_of(V6_SPACE):
            raise InvalidInput("prefix outside 2001:db8::/32")
    except TypeError as exc:
        raise InvalidInput("bad prefix family") from exc
    return net


def validate_manifest(obj):
    if not isinstance(obj, dict):
        raise InvalidInput("manifest must be an object")
    if set(obj.keys()) != TOP_KEYS:
        raise InvalidInput("manifest has unknown or missing keys")

    if not is_int(obj["version"]) or obj["version"] != 1:
        raise InvalidInput("version must be integer 1")
    seed = obj["seed"]
    if not is_int(seed) or not (0 <= seed <= (1 << 64) - 1):
        raise InvalidInput("seed out of range")
    low_count = obj["low_count"]
    if not is_int(low_count) or not (1 <= low_count <= 32):
        raise InvalidInput("low_count out of range")
    attempts = obj["attempts"]
    if not is_int(attempts) or not (1 <= attempts <= 3):
        raise InvalidInput("attempts out of range")
    spacing = obj["spacing_ms"]
    if not is_int(spacing) or not (1 <= spacing <= 1000):
        raise InvalidInput("spacing_ms out of range")
    timeout = obj["timeout_ms"]
    if not is_int(timeout) or not (1 <= timeout <= 1000000):
        raise InvalidInput("timeout_ms out of range")

    windows = obj["windows"]
    if not isinstance(windows, list) or not (0 <= len(windows) <= 8):
        raise InvalidInput("windows must be a list of at most 8")

    seen_window_ids = set()
    total_selected = 0
    parsed_windows = []
    for win in windows:
        if not isinstance(win, dict) or set(win.keys()) != WINDOW_KEYS:
            raise InvalidInput("invalid window object")
        wid = win["id"]
        if not isinstance(wid, str) or not ID_RE.match(wid):
            raise InvalidInput("invalid window id")
        if wid in seen_window_ids:
            raise InvalidInput("duplicate window id")
        seen_window_ids.add(wid)
        start = win["start_ms"]
        if not is_int(start) or not (0 <= start <= 10 ** 12):
            raise InvalidInput("start_ms out of range")
        scopes = win["scopes"]
        if not isinstance(scopes, list) or not (0 <= len(scopes) <= 32):
            raise InvalidInput("scopes must be a list of at most 32")
        seen_scope_ids = set()
        parsed_scopes = []
        selected_bases = set()
        for scope in scopes:
            if not isinstance(scope, dict) or set(scope.keys()) != SCOPE_KEYS:
                raise InvalidInput("invalid scope object")
            sid = scope["id"]
            if not isinstance(sid, str) or not ID_RE.match(sid):
                raise InvalidInput("invalid scope id")
            if sid in seen_scope_ids:
                raise InvalidInput("duplicate scope id within window")
            seen_scope_ids.add(sid)
            net = parse_prefix(scope["prefix"])
            subnets = scope["subnets"]
            if not isinstance(subnets, list):
                raise InvalidInput("subnets must be a list")
            if net.prefixlen == 64:
                if len(subnets) != 1 or not is_int(subnets[0]) or subnets[0] != 0:
                    raise InvalidInput("subnets for /64 must be exactly [0]")
            else:
                if not (1 <= len(subnets) <= 256):
                    raise InvalidInput("subnets count out of range")
                seen = set()
                for s in subnets:
                    if not is_int(s) or not (0 <= s <= 255):
                        raise InvalidInput("subnet value out of range")
                    if s in seen:
                        raise InvalidInput("duplicate subnet")
                    seen.add(s)
            base_int = int(net.network_address)
            for s in subnets:
                sel = base_int + (s << 64) if net.prefixlen == 56 else base_int
                if sel in selected_bases:
                    raise InvalidInput("selected /64 overlaps within window")
                selected_bases.add(sel)
            total_selected += len(subnets)
            parsed_scopes.append((sid, net, list(subnets)))
        parsed_windows.append((wid, start, parsed_scopes))
    if total_selected > 2048:
        raise InvalidInput("too many selected /64s")
    return {
        "seed": seed, "low_count": low_count, "attempts": attempts,
        "spacing_ms": spacing, "timeout_ms": timeout,
        "windows": parsed_windows,
    }


def load_manifest(path):
    raw = read_bounded(path, MANIFEST_LIMIT)
    obj = decode_json(raw)
    return validate_manifest(obj)


# --------------------------------------------------------------------------
# Planning
# --------------------------------------------------------------------------
def derive_canary(seed, window_id, scope_id, canonical64):
    material = ("ipv6-evidence-v1\n" + str(seed) + "\n" + window_id + "\n" +
                scope_id + "\n" + canonical64 + "\n").encode("ascii")
    digest = hashlib.sha256(material).digest()
    c0 = int.from_bytes(digest[:8], "big") | (1 << 63)
    return c0


def build_plan(man):
    seed = man["seed"]
    low_count = man["low_count"]
    attempts = man["attempts"]
    spacing = man["spacing_ms"]
    timeout = man["timeout_ms"]

    probes_out = []
    probe_meta = {}
    segments = []

    for wid, start, scopes in sorted(man["windows"], key=lambda w: w[0]):
        q = 0
        for sid, net, subnets in sorted(scopes, key=lambda s: s[0]):
            prefix_int = int(net.network_address)
            for subnet in sorted(subnets):
                if net.prefixlen == 56:
                    base_int = prefix_int + (subnet << 64)
                else:
                    base_int = prefix_int
                network_str = str(ipaddress.IPv6Address(base_int)) + "/64"
                c0 = derive_canary(seed, wid, sid, network_str)
                seg_index = len(segments)
                low_targets = []
                canary_targets = []
                sched = []  # (role, slot, target_int)
                for iid in range(1, low_count + 1):
                    sched.append(("low", iid, base_int | iid))
                    low_targets.append((iid, base_int | iid))
                sched.append(("canary", 0, base_int | c0))
                sched.append(("canary", 1, base_int | (c0 ^ 1)))
                canary_targets.append((0, base_int | c0))
                canary_targets.append((1, base_int | (c0 ^ 1)))
                for role, slot, target_int in sched:
                    target_str = str(ipaddress.IPv6Address(target_int))
                    for attempt in range(attempts):
                        sent = start + q * spacing
                        deadline = sent + timeout
                        pid = "%s/%s/%d/%s-%d/%d" % (
                            wid, sid, subnet, role, slot, attempt)
                        probes_out.append({
                            "id": pid,
                            "window": wid,
                            "scope": sid,
                            "subnet": subnet,
                            "target": target_str,
                            "role": role,
                            "slot": slot,
                            "attempt": attempt,
                            "sent_ms": sent,
                            "deadline_ms": deadline,
                        })
                        probe_meta[pid] = (target_int, sent, deadline)
                        q += 1
                segments.append({
                    "window": wid,
                    "scope": sid,
                    "subnet": subnet,
                    "network": network_str,
                    "low_targets": low_targets,  # list of (iid, target_int)
                    "canary_slots": [(0, base_int | c0), (1, base_int | (c0 ^ 1))],
                })
    return probes_out, probe_meta, segments


def make_plan(manifest_path):
    man = load_manifest(manifest_path)
    probes_out, _meta, _segs = build_plan(man)
    return {"version": 1, "probes": probes_out}


# --------------------------------------------------------------------------
# Address parsing for replay rows
# --------------------------------------------------------------------------
def parse_address(text):
    if not isinstance(text, str):
        raise InvalidInput("address not string")
    if "%" in text or any(ch.isspace() for ch in text):
        raise InvalidInput("address zone/whitespace")
    try:
        addr = ipaddress.IPv6Address(text)
    except ValueError as exc:
        raise InvalidInput("bad address") from exc
    if not addr in V6_SPACE:
        raise InvalidInput("address outside 2001:db8::/32")
    return int(addr)


# --------------------------------------------------------------------------
# Replay ingestion
# --------------------------------------------------------------------------
def split_rows(data):
    rows = []
    if not data:
        return rows
    pieces = data.split(b"\n")
    if data.endswith(b"\n"):
        pieces = pieces[:-1]
        for p in pieces:
            rows.append((p, len(p) + 1))
    else:
        last = len(pieces) - 1
        for i, p in enumerate(pieces):
            if i < last:
                rows.append((p, len(p) + 1))
            else:
                rows.append((p, len(p)))
    return rows


def replay(manifest_path, responses_path):
    man = load_manifest(manifest_path)
    _probes, probe_meta, segments = build_plan(man)
    attempts = man["attempts"]

    data = read_bounded(responses_path, REPLAY_LIMIT)
    rows = split_rows(data)
    if len(rows) > MAX_LINES:
        raise InvalidInput("too many physical lines")

    diagnostics = []
    accepted_rows = 0
    duplicate_rows = 0
    seen = set()
    accepted_by_probe = {}

    for idx, (content, byte_len) in enumerate(rows):
        line_no = idx + 1
        if byte_len > MAX_LINE_BYTES:
            raise InvalidInput("physical line too long")
        # json check
        try:
            obj = decode_json(content)
        except InvalidInput:
            diagnostics.append({"line": line_no, "reason": "json"})
            continue
        # schema
        if not isinstance(obj, dict) or set(obj.keys()) != ROW_KEYS:
            diagnostics.append({"line": line_no, "reason": "schema"})
            continue
        probe_id = obj["probe_id"]
        target = obj["target"]
        source = obj["source"]
        if (not isinstance(probe_id, str) or not isinstance(target, str)
                or not isinstance(source, str)):
            diagnostics.append({"line": line_no, "reason": "schema"})
            continue
        if len(probe_id) == 0 or len(probe_id) > 200:
            diagnostics.append({"line": line_no, "reason": "schema"})
            continue
        if (not is_int(obj["received_ms"]) or not is_int(obj["type"])
                or not is_int(obj["code"])):
            diagnostics.append({"line": line_no, "reason": "schema"})
            continue
        # address
        try:
            target_int = parse_address(target)
            source_int = parse_address(source)
        except InvalidInput:
            diagnostics.append({"line": line_no, "reason": "address"})
            continue
        # unknown_probe
        meta = probe_meta.get(probe_id)
        if meta is None:
            diagnostics.append({"line": line_no, "reason": "unknown_probe"})
            continue
        planned_target, sent, deadline = meta
        # target_mismatch
        if target_int != planned_target:
            diagnostics.append({"line": line_no, "reason": "target_mismatch"})
            continue
        # time
        received = obj["received_ms"]
        if not (sent <= received < deadline):
            diagnostics.append({"line": line_no, "reason": "time"})
            continue
        # icmp
        typ = obj["type"]
        code = obj["code"]
        if not (typ == 129 and code == 0) and not (
                typ == 1 and 0 <= code <= 6):
            diagnostics.append({"line": line_no, "reason": "icmp"})
            continue

        key = (probe_id, received, target_int, source_int, typ, code)
        if key in seen:
            duplicate_rows += 1
            continue
        seen.add(key)
        accepted_rows += 1
        accepted_by_probe.setdefault(probe_id, []).append(
            (source_int, typ, code))

    seg_results = reconcile(segments, accepted_by_probe, attempts)
    return {
        "version": 1,
        "accepted_rows": accepted_rows,
        "duplicate_rows": duplicate_rows,
        "diagnostics": diagnostics,
        "segments": seg_results,
    }


# --------------------------------------------------------------------------
# Evidence reconciliation
# --------------------------------------------------------------------------
def reconcile(segments, accepted_by_probe, attempts):
    results = []
    for seg in segments:
        wid = seg["window"]
        sid = seg["scope"]
        subnet = seg["subnet"]

        # canary hits
        canary_hits = []
        for slot, ctarget in seg["canary_slots"]:
            hit = False
            for attempt in range(attempts):
                pid = "%s/%s/%d/canary-%d/%d" % (wid, sid, subnet, slot, attempt)
                for (src, typ, code) in accepted_by_probe.get(pid, ()):
                    if typ == 129 and code == 0 and src == ctarget:
                        hit = True
                        break
                if hit:
                    break
            if hit:
                canary_hits.append(slot)
        canary_hits.sort()

        internal = set()
        external = set()
        targets_out = []

        for iid, target_int in seg["low_targets"]:
            internal_attempts = []
            external_attempts = []
            external_sources = set()
            silent_attempts = []
            for attempt in range(attempts):
                pid = "%s/%s/%d/low-%d/%d" % (wid, sid, subnet, iid, attempt)
                prow = accepted_by_probe.get(pid)
                if not prow:
                    silent_attempts.append(attempt)
                    continue
                got_internal = False
                got_external = False
                for (src, typ, code) in prow:
                    if typ == 129 and code == 0 and src == target_int:
                        got_internal = True
                    elif typ == 1 and 0 <= code <= 6 and src != target_int:
                        got_external = True
                        external_sources.add(src)
                if got_internal:
                    internal_attempts.append(attempt)
                    internal.add(target_int)
                if got_external:
                    external_attempts.append(attempt)
                    external.add(src)
            # external accumulated already via set adds inside loop
            for src in external_sources:
                external.add(src)
            targets_out.append({
                "address_int": target_int,
                "internal_attempts": internal_attempts,
                "external_attempts": external_attempts,
                "external_sources": external_sources,
                "silent_attempts": silent_attempts,
            })

        overlap = internal & external
        if len(canary_hits) == 2:
            state = "alias_suspect"
        elif overlap:
            state = "ambiguous"
        else:
            state = "usable"

        if state != "usable":
            exposure = "excluded"
        elif internal:
            exposure = "observed_internal_reply"
        else:
            exposure = "inconclusive"

        target_objs = []
        for t in targets_out:
            ti = t["address_int"]
            if state == "alias_suspect":
                classification = "alias_suspect"
            elif state == "ambiguous":
                classification = "ambiguous"
            else:
                has_int = ti in internal
                has_ext = bool(t["external_sources"])
                if has_int and has_ext:
                    classification = "mixed"
                elif has_int:
                    classification = "internal"
                elif has_ext:
                    classification = "external"
                else:
                    classification = "unknown"
            target_objs.append({
                "address": str(ipaddress.IPv6Address(ti)),
                "classification": classification,
                "internal_attempts": t["internal_attempts"],
                "external_attempts": t["external_attempts"],
                "external_sources": [str(ipaddress.IPv6Address(s))
                                     for s in sorted(t["external_sources"])],
                "silent_attempts": t["silent_attempts"],
            })

        results.append({
            "window": wid,
            "scope": sid,
            "subnet": subnet,
            "network": seg["network"],
            "state": state,
            "exposure": exposure,
            "canary_hits": canary_hits,
            "internal": [str(ipaddress.IPv6Address(a)) for a in sorted(internal)],
            "external": [str(ipaddress.IPv6Address(a)) for a in sorted(external)],
            "overlap": [str(ipaddress.IPv6Address(a)) for a in sorted(overlap)],
            "targets": target_objs,
        })
    return results


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------
def main():
    parser = argparse.ArgumentParser(add_help=False)
    if any(arg in {"-h", "--help"} for arg in sys.argv[1:]):
        parser.error("help switches are not supported")
    sub = parser.add_subparsers(dest="command", required=True)
    plan = sub.add_parser("plan", add_help=False)
    plan.add_argument("manifest")
    replay_parser = sub.add_parser("replay", add_help=False)
    replay_parser.add_argument("manifest")
    replay_parser.add_argument("responses")
    args = parser.parse_args()
    try:
        if args.command == "plan":
            result = make_plan(args.manifest)
        else:
            result = replay(args.manifest, args.responses)
    except (ValueError, OSError, NotImplementedError) as error:
        print(str(error), file=sys.stderr)
        return 2
    sys.stdout.write(json.dumps(result, separators=(",", ":"), allow_nan=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
